# spscring.map — the functions libspscring.so exports, under the version node SPSCRING_<major> (the soname major): exactly the
# functions app/spscring.h declares (the `function` lines of abi/layout.txt; utils/check_abi.sh --exports refuses any difference).
# Everything else stays local. The .a archive is unaffected.
SPSCRING_1 {
  global:
    spsc_ring_capacity;
    spsc_ring_destroy;
    spsc_ring_init;
    spsc_ring_is_empty;
    spsc_ring_is_full;
    spsc_ring_pop;
    spsc_ring_push;
    spsc_ring_reset;
    spsc_ring_size;
  local:
    *;
};
